%% Wind Turbine Data Generation
% Time vectors
time = 0:1:60;              % Coarse sampling time (s)
numSamples = numel(time);

% Wind speed components (m/s)
baseWind = 8;                           % Mean wind speed
gustWind = 1.5 * sin(0.1 * time);      % Slow sinusoidal variation
turbWind = 0.5 * randn(1, numSamples); % Random turbulence

% Composite wind speed with physical constraint
windMeasured = baseWind + gustWind + turbWind;
windMeasured(windMeasured < 0) = 0;  % Enforce non-negative

%% Interpolation - Estimate Values Between Points
timeFine = 0:0.1:60;  % Fine-resolution time vector
windInterp = interp1(time, windMeasured, timeFine, 'pchip');

%% Curve Fitting - Extract Overall Trend
polyCoeffs = polyfit(time, windMeasured, 1);  % Linear trend coefficients
windTrend = polyval(polyCoeffs, timeFine);

%% Visualization
figure('Name', 'Wind Speed Analysis', 'NumberTitle', 'off'); %[output:15851b05]

% Subplot 1: Interpolation
subplot(2, 1, 1) %[output:15851b05]
plot(time, windMeasured, 'o', 'LineWidth', 1.5, 'DisplayName', 'Measured Data') %[output:15851b05]
hold on %[output:15851b05]
plot(timeFine, windInterp, '-', 'LineWidth', 2, 'DisplayName', 'Interpolated (PCHIP)') %[output:15851b05]
grid on %[output:15851b05]
xlabel('Time (s)') %[output:15851b05]
ylabel('Wind Speed (m/s)') %[output:15851b05]
title('Interpolation of Wind Speed') %[output:15851b05]
legend('Location', 'best') %[output:15851b05]

% Subplot 2: Curve Fitting
subplot(2, 1, 2) %[output:15851b05]
plot(time, windMeasured, 'o', 'LineWidth', 1.5, 'DisplayName', 'Measured Data') %[output:15851b05]
hold on %[output:15851b05]
plot(timeFine, windTrend, '-', 'LineWidth', 2, 'DisplayName', 'Linear Trend') %[output:15851b05]
grid on %[output:15851b05]
xlabel('Time (s)') %[output:15851b05]
ylabel('Wind Speed (m/s)') %[output:15851b05]
title('Curve Fitting - Linear Trend') %[output:15851b05]
legend('Location', 'best') %[output:15851b05]

